// Assemble the Anvil Mechanical theme (6 Divi 5 pages for a commercial and industrial plumbing contractor) into one pack. Unlike create-real-estate-pack.ts the pages are NOT
// generated by the pipeline's Claude workers: they are composed by the AI Editor for
// Divi 5 plugin from its section recipes (design language organic-warm + a style kit,
// validated by the real LayoutGate) in the validator repo:
//   php scripts/theme-packs/build.php anvil         -> dist/theme-packs/anvil/<role>.json
// and then run through every downstream gate here (validate, stock photos, design lint,
// mobile stacking, dedupe, SEO, real Divi render, critics, ingest).
//
//   npm run dev            # in another shell (ingest target)
//   set -a && . ./.env.local && set +a && ANV_DIR=<dir with the six json files> npx tsx scripts/create-anvil-pack.ts
// Smoke test: THEME_ONLY_ROLES=home.
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { eq, inArray } from 'drizzle-orm';
import { db } from '@/db/client';
import { packs, packLayouts, layouts } from '@/db/schema';
import { buildThemeDeps } from '@/pipeline/deps';
import { runThemePack, themePageSlug, type ThemeSpec, type ThemePage } from '@/pipeline/theme';
import type { Brief } from '@/pipeline/compose';

const DIR = process.env.ANV_DIR ?? '../Divi 5 Deterministic Validator/dist/theme-packs/anvil';

const BRIEF: Brief = {
  businessType: 'service/agency',
  businessName: 'Anvil Mechanical',
  tagline: 'Built to run when everything depends on it.',
  audience: 'facility managers, property managers, restaurant owners and plant operators who need a licensed commercial plumbing contractor with 24-hour response',
  conversionGoal: 'request a quote',
  primaryCta: 'Request a quote',
  accentColorHex: '#7C9CFF',
  voice: 'blunt, confident and plain-spoken. Short sentences, hard numbers, no fluff and no plumbing puns.',
  palette: { primary: '#7c9cff', secondary: '#9aa4c0', tint: '#151c33', dark: '#0b1020', heading: '#f2f4fa', body: '#9aa4c0' },
  designNotes: 'Glass-dark design language with the heavy-block button kit: a deep navy ground, layered cards with a light border, electric blue accent, Inter throughout and heavy outlined buttons.',
};

const BRAND_FACTS =
  'Anvil Mechanical, 2210 S Canal Street, Chicago, IL 60616. Phone (312) 555-0118. hello@anvilmechanical.com. ' +
  'Sample copy: names, prices and reviews are examples to replace.';

const ROLES: { role: string; roleLabel: string }[] = [
  { role: 'home', roleLabel: 'Home' },
  { role: 'services', roleLabel: 'Services' },
  { role: 'projects', roleLabel: 'Projects' },
  { role: 'emergency', roleLabel: 'Emergency & Plans' },
  { role: 'about', roleLabel: 'About' },
  { role: 'contact', roleLabel: 'Contact' },
];

const PAGES: ThemePage[] = ROLES.map((r) => ({
  ...r,
  flow: [],
  precomposed: readFileSync(`${DIR}/${r.role}.json`, 'utf8'),
}));

const SPEC: ThemeSpec = { niche: 'plumbing', style: 'dark', color: 'blue', brief: BRIEF, brandFacts: BRAND_FACTS, pages: PAGES };

const PACK_SLUG = 'anvil-commercial-plumbing-theme';
const PACK_TITLE = 'Anvil: Dark Commercial Plumbing & Contractor Theme (6 Pages)';
const PRICE_CENTS = 1200;
const DESCRIPTION =
  'A complete six-page Divi 5 website for a commercial or industrial plumbing contractor, mechanical firm or any trade ' +
  'business that sells on reliability, ready to make your own. Home, Services, Projects, Emergency & Plans, About and ' +
  'Contact share one dark, bold identity: a deep navy ground, layered cards with a light border, an electric blue accent, ' +
  'Inter type and heavy outlined buttons. Every section is built from proven, validated recipes and a single design ' +
  'language and style kit, so buttons, accordions, forms and type match on every page, on desktop, tablet and phone. A ' +
  'photographic hero, a proof-numbers band, a capabilities grid, a projects portfolio, an emergency-response walkthrough ' +
  'with plan pricing, a team page with a founder note, FAQs and a quote form with the company details are all in place. ' +
  'Names, prices, hours and reviews are sample copy: swap in your own and publish. No lorem ipsum, no broken layouts. One ' +
  'simple commercial license, unlimited client sites.';
const PACK_SEO = {
  metaTitle: 'Anvil: Dark Commercial Plumbing Theme for Divi 5 (6 Pages) | Divi5Lab',
  metaDescription:
    'A complete six-page dark Divi 5 website theme for a commercial plumbing or mechanical contractor: Home, Services, ' +
    'Projects, Emergency & Plans, About and Contact. One bold brand, real copy, portfolio, plans and quote sections.',
  keywords: [
    'divi 5 commercial plumbing theme', 'dark plumber website template', 'mechanical contractor divi template',
    'industrial contractor divi 5 theme', 'trade business website template', 'divi 5 multi-page theme',
  ],
};

async function upsertPack(slugs: string[]): Promise<void> {
  const rows = await db
    .select({ id: layouts.id, slug: layouts.slug, previews: layouts.previewImageKeys })
    .from(layouts).where(inArray(layouts.slug, slugs));
  const bySlug = new Map(rows.map((r) => [r.slug, r]));
  const found = slugs.filter((s) => bySlug.has(s));
  if (found.length === 0) { console.error('no Anvil pages found in DB — did ingest run?'); process.exitCode = 1; return; }
  if (found.length < slugs.length) console.warn(`only ${found.length}/${slugs.length} pages present; linking what exists`);

  const cover = bySlug.get(slugs[0])?.previews?.[0] ?? bySlug.get(found[0])!.previews?.[0] ?? null;
  const existing = (await db.select().from(packs).where(eq(packs.slug, PACK_SLUG)).limit(1))[0];
  const common = {
    title: PACK_TITLE, description: DESCRIPTION, kind: 'paid' as const,
    priceCents: PRICE_CENTS, stripePriceId: null, coverImageKey: cover, seo: PACK_SEO, status: 'published' as const,
  };
  let packId: string;
  if (existing) {
    packId = existing.id;
    await db.update(packs).set(common).where(eq(packs.id, packId));
  } else {
    packId = randomUUID();
    await db.insert(packs).values({ id: packId, slug: PACK_SLUG, ...common });
  }

  await db.delete(packLayouts).where(eq(packLayouts.packId, packId));
  await db.insert(packLayouts).values(found.map((s, i) => ({ packId, layoutId: bySlug.get(s)!.id, position: i })));

  console.log(`\nPack ready: /packs/${PACK_SLUG}  (paid, ${found.length} pages, cover=${cover ? 'set' : 'none'})`);
}

async function main() {
  const { deps, close } = await buildThemeDeps({ businessName: BRIEF.businessName, logPrefix: '[theme]', defaultMaxBudgetUsd: 1 });

  // Optional smoke-test knob: THEME_ONLY_ROLES=home,listings limits which pages generate.
  const onlyRoles = (process.env.THEME_ONLY_ROLES ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const spec: ThemeSpec = onlyRoles.length ? { ...SPEC, pages: SPEC.pages.filter((p) => onlyRoles.includes(p.role)) } : SPEC;

  console.log(`[theme] generating ${spec.pages.length} ${spec.niche} pages for "${BRIEF.businessName}"…`);
  const result = await runThemePack(spec, deps);
  await close();
  console.log('[theme] summary:', { generated: result.generated, ingested: result.ingested, dropped: result.dropped, deduped: result.deduped });

  if (onlyRoles.length) { console.log('[theme] partial run (THEME_ONLY_ROLES set) — skipping pack assembly'); return; }
  const expectedSlugs = SPEC.pages.map((p) => themePageSlug(BRIEF, SPEC, p));
  await upsertPack(expectedSlugs);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
